ProjectALife.DialogueShards["scenes_panic_days_4"] = {
{"fw_ld7_pma_0045","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|day=0,4|mood=grim",{1,"How many more checkpoints between here and Louisville?",2,"Four, maybe five",1,"And all closed?",2,"Closed, they're all closed, unless you've got the right paper"}},
{"fw_ld7_pma_0046","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|day=0,4|mood=fear",{1,"Is that one of yours, in the ditch? Is he moving?",2,"Don't look",1,"I SAW him move!",2,"I know, I'm aware, that's why I'm not letting you go over there, stay put"}},
{"fw_ld7_pma_0047","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|x1=f|day=0,4|mood=angry",{1,"Why are you guys just standing around?",2,"Because we're holding, and that's the job",1,"Holding while people die!",2,"Yes, ma'am, exactly, you've nailed it, I think about it every minute"}},
{"fw_ld7_pma_0048","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|day=0,4|mood=sad",{1,"Do you pray?",2,"Not before today",1,"And today?",2,"Today I've been asking for just a plain old phone call from anybody"}},
{"fw_ld7_pma_0049","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|tmp=fresh|day=0,4|mood=fear",{1,"What do I do if one of them comes at me?",2,"You hit it in the head, hard, and then you run",1,"How hard?",2,"As hard as you've ever hit anything in your life, and then harder"}},
{"fw_ld7_pma_0050","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|x1=f|day=0,4|mood=angry",{1,"Would you give a family a ride if you could?",2,"I'd want to help. Couldn't promise a ride without checking what was possible",1,"Even if it meant leaving a post?",2,"I'd have to work out who was depending on me there too. Not an answer I'd make lightly"}},
{"fw_ld7_pma_0051","panic_days",2,"reg=civilian,family,worker,rescue,military|r1=civilian,family,worker,rescue|r2=military|day=0,4|mood=grim",{1,"The man at the gate told us to go back",2,"Yeah, that sounds right",1,"To where? Our house is on the other side!",2,"Then I guess you're stuck on this side of a lot of things, I'm sorry"}},
{"fw_ld7_pma_0052","panic_days",2,"reg=military|day=0,4|mood=grim",{1,"Command's still not answering",2,"Try again",1,"I've tried forty times, it's just carrier hiss",2,"Then try forty-one, somebody has to pick up eventually"}},
{"fw_ld7_pma_0053","panic_days",2,"reg=military|day=0,4|mood=fear",{1,"Hold fire! HOLD FIRE! Is he infected? Is he infected?!",2,"He's limping, he's got a tear in his sleeve",1,"That's not what I asked!",2,"I can't see his arm, I can't see it, wait for the Sergeant!"}},
{"fw_ld7_pma_0054","panic_days",2,"reg=military|tmp=fresh|day=0,4|mood=fear",{1,"I can't do it, I can't, it's a person, it was a person",2,"It's not a person now",1,"It had a name tag, it had a NAME TAG",2,"Then don't read it, don't ever read the tag, hear me"}},
{"fw_ld7_pma_0055","panic_days",2,"reg=military|day=0,4|mood=grim",{1,"How many mags have you got?",2,"Three",1,"Me too",2,"That's nothing, that's an afternoon, that's nothing"}},
{"fw_ld7_pma_0056","panic_days",2,"reg=military|day=0,4|mood=angry",{1,"Are we supposed to shoot civilians?",2,"Nobody said",1,"Somebody has to SAY!",2,"Then go ask, go find the guy who knows, and when you do, come tell me"}},
{"fw_ld7_pma_0057","panic_days",2,"reg=military|day=0,4|mood=grim",{1,"The rules of engagement came down",2,"And?",1,"Hold fire unless fired upon",2,"They're not firing, they're just walking at us"}},
{"fw_ld7_pma_0058","panic_days",2,"reg=military|day=0,4|mood=fear",{1,"Mendoza's gone, I saw him walk off the line",2,"Walk off? Where to?",1,"Toward the houses, with his rifle slung, like he was going to the corner store",2,"Leave it, we can't go after him, we can't leave our spot"}},
{"fw_ld7_pma_0059","panic_days",2,"reg=military|day=0,4|mood=grim",{1,"I need water",2,"We're rationing",1,"I'm rationing myself, I haven't had any since noon",2,"Take a sip of mine, one, don't tell anybody, I'm serious, don't tell anybody"}},
{"fw_ld7_pma_0060","panic_days",2,"reg=military|day=0,4|mood=funny",{1,"Beef stew again",2,"At least it's not the omelet",1,"Nobody should do that to an egg",2,"Nobody should do that to a person, hahaha, God, I'm tired"}},
{"fw_ld7_pma_0061","panic_days",2,"reg=military|day=0,4|mood=fear",{1,"I got somebody on the net, I think it's Louisville",2,"What are they saying?",1,"They're saying \"help,\" that's it, \"help,\" over and over",2,"Keep listening, don't answer, don't give anything away"}},
{"fw_ld7_pma_0062","panic_days",2,"reg=military|day=0,4|mood=grim",{1,"Is it true we can't go in?",2,"We go where they tell us",1,"Nobody's telling us anything!",2,"Then we stay where we are, it's a short list of orders, I know"}},
{"fw_ld7_pma_0063","panic_days",2,"reg=military|day=0,4|mood=sad",{1,"My mom thinks I'm in Germany",2,"Mine thinks I'm at a barbecue",1,"I should've called her, before the lines went",2,"She knows, they always know"}},
{"fw_ld7_pma_0064","panic_days",2,"reg=military|day=0,4|mood=fear",{1,"Do we put on the masks?",2,"Nobody said",1,"What if it's in the air?",2,"Then we're already breathing it, so wear it if you're gonna feel better, I'm not stopping you"}},
{"fw_ld7_pma_0065","panic_days",2,"reg=military|day=0,4|mood=angry",{1,"Watch your ammo, don't waste it!",2,"Waste what? I've got nine rounds!",1,"Then nine's what we've got, so quit firing at shadows!",2,"It wasn't a shadow, but fine, nine it is"}},
{"fw_ld7_pma_0066","panic_days",2,"reg=military|day=0,4|mood=fear",{1,"One of our guys got hit, is it a bite?",2,"No, he fell off the berm",1,"Check him, check him anyway",2,"Roll up your sleeve, all the way, I need to see it, it's not an insult"}},
{"fw_ld7_pma_0067","panic_days",2,"reg=military|day=0,4|mood=angry",{1,"We should leave",2,"That's desertion",1,"Is it still desertion if there's no army?",2,"...I don't know, I'd like to not find out"}},
{"fw_ld7_pma_0068","panic_days",2,"reg=military|day=0,4|mood=sad",{1,"Stop humming that cadence",2,"It helps",1,"It's a cadence, it's meant for marching, it's not helping, it's the same four lines",2,"Fine, fine, I'll just hum it in my head, you won't hear it"}},
{"fw_ld7_pma_0069","panic_days",2,"reg=military|day=0,4|mood=grim",{1,"The lieutenant's gone",2,"Then who's in command?",1,"Whoever's loudest, I guess",2,"Then nobody's in command, because I'm not yelling, I'm tired"}},
{"fw_ld7_pma_0070","panic_days",2,"reg=military|day=0,4|mood=sad",{1,"Do you think they'll court-martial me for crying?",2,"Everybody's crying",1,"I'm not kidding",2,"Neither am I, I did it behind the supply tent an hour ago, you're in good company"}},
{"fw_ld7_pma_0071","panic_days",2,"reg=military|tmp=fresh|day=0,4|mood=fear",{1,"Mag in, tap, rack, aim, squeeze, mag in, tap, rack-",2,"Slow down",1,"I can't slow down! I have to remember it! I have to!",2,"You remember it, I'm watching you, you remember it fine, slow down"}},
{"fw_ld7_pma_0072","panic_days",2,"reg=military|day=0,4|mood=angry",{1,"We're out of gas",2,"How can we be out of gas?",1,"Because nobody's been refilling anything, because nobody's here to refill it!",2,"Then we walk, I've walked further for worse reasons"}},
{"fw_ld7_pma_0073","panic_days",2,"reg=military|day=0,4|mood=fear",{1,"Are you awake?",2,"Yes",1,"You've been awake too long, your eyes are the wrong color",2,"I'm fine, I'm fine, I just need to blink, I can't blink, they'll- if I blink-"}},
{"fw_ld7_pma_0074","panic_days",2,"reg=military|day=0,4|mood=grim",{1,"How's the line?",2,"Quiet",1,"Quiet's worse",2,"I know, I wrote it on my hand, don't trust quiet"}},
{"fw_ld7_pma_0075","panic_days",2,"reg=military|day=0,4|mood=fear",{1,"What's that sound? Hear it? That dragging?",2,"Probably a trash can",1,"Trash cans don't moan",2,"...okay, it's not a trash can, thumb your selector, easy"}},
{"fw_ld7_pma_0076","panic_days",2,"reg=military|day=0,4|mood=angry",{1,"They told us this was a training exercise",2,"Then it's the worst exercise ever",1,"They told us there'd be blanks!",2,"Then somebody didn't read the paperwork, and I've never been so glad to be wrong about paperwork"}},
{"fw_ld7_pma_0077","panic_days",2,"reg=military|day=0,4|mood=grim",{1,"I counted nineteen of us when this started",2,"And now?",1,"Fourteen",2,"Okay, don't count again, just don't"}},
{"fw_ld7_pma_0078","panic_days",2,"reg=military|day=0,4|mood=fear",{1,"Get down, get down, it's coming from the left!",2,"I don't see anything",1,"It's behind the dumpster, listen, you can hear it",2,"Okay, I hear it, hold, hold, wait for it to step out"}},
{"fw_ld7_pma_0079","panic_days",2,"reg=military|day=0,4|mood=sad",{1,"What's the date?",2,"Does it matter?",1,"I just want to know what day I'm gonna remember",2,"Pick one, any one, I'll back you up"}},
{"fw_ld7_pma_0080","panic_days",2,"reg=military|tmp=fresh|day=0,4|mood=fear",{1,"Sarge said not to look at the faces",2,"I looked",1,"And?",2,"One of them had a dog tag, same as ours, same exact kind"}},
{"fw_ld7_pma_0081","panic_days",2,"reg=military|day=0,4|mood=angry",{1,"Every time I ask a question they tell me to stand by",2,"So stand by",1,"I've been standing by since the first siren! My legs are made of stand by!",2,"Hahaha- sorry, sorry, that's good, that's actually good"}},
{"fw_ld7_pma_0082","panic_days",2,"reg=military|day=0,4|mood=grim",{1,"You getting used to it yet?",2,"To what?",1,"The noise, the smell, the guys you don't see anymore",2,"No, you don't, you just get quieter"}},
{"fw_ld7_pma_0083","panic_days",2,"reg=military|day=0,4|mood=fear",{1,"I can't keep track! Slow down, let me look!",2,"Say again, say again!",1,"Eight, I said eight, they're coming over the hill!",2,"Then fall back, fall BACK, I'm right behind you!"}},
{"fw_ld7_pma_0084","panic_days",2,"reg=military|day=0,4|mood=sad",{1,"I wrote my sister a letter",2,"How are you gonna send it?",1,"I don't know, I'll keep it in my boot",2,"Put my name in it too, say I said hey"}},
{"fw_ld7_pma_0085","panic_days",2,"reg=military|day=0,4|mood=grim",{1,"Who's got the keys to the armory?",2,"The sergeant",1,"Where's the sergeant?",2,"Where's everybody, man, where's everybody"}},
{"fw_ld7_pma_0086","panic_days",2,"reg=military|day=0,4|mood=fear",{1,"Is that a flare? Somebody fired a flare!",2,"Where?",1,"Over the ridge, red, it's red!",2,"Red means trouble, red means stay, red means every kind of bad thing, I don't know"}},
{"fw_ld7_pma_0087","panic_days",2,"reg=military|day=0,4|mood=calm",{1,"You scared?",2,"Yes",1,"Good, so'm I, it keeps us honest",2,"Honest about what?",1,"Honest about not being heroes, I never wanted to be one anyway"}},
{"fw_ld7_poa_0001","panic_days",2,"reg=outlaw,raider,gang,club,crime,prison|day=0,4|mood=fear",{1,"Cops are busy, boys, that's all I'm saying",2,"Busy with WHAT? Did you see what's out there?",1,"I saw it, I saw it, I'm just saying it's our chance",2,"Chance for what? To get bit?"}},
{"fw_ld7_poa_0002","panic_days",2,"reg=outlaw,raider,gang,club,crime,prison|day=0,4|mood=grim",{1,"Transport rolled over, nobody came, so we walked",2,"Guards ran first, I seen 'em",1,"Everybody's running and nobody's chasing, that's the weird part",2,"Somebody's chasing, just not us, not yet"}},
{"fw_ld7_poa_0003","panic_days",2,"reg=outlaw,raider,gang,club,crime,prison|day=0,4|mood=funny",{1,"I had eleven months left on a bad check and now THIS",2,"Hahaha, you're a lucky son of a bitch",1,"Lucky? I was gonna do my time and go home!",2,"Home's gone, brother, welcome to freedom"}},
{"fw_ld7_poa_0004","panic_days",2,"reg=outlaw,raider,gang,club,crime,prison|day=0,4|mood=fear",{1,"What the fuck was that sound?",2,"Don't tell me",1,"It's coming from the lot, it sounds like a cow, like a- somebody's moaning",2,"It's not somebody, shut up, it's not a somebody, keep walking"}},
{"fw_ld7_poa_0005","panic_days",2,"reg=outlaw,raider,gang,club,crime,prison|day=0,4|mood=grim",{1,"Club meeting's canceled",2,"Everything's canceled",1,"Where's the prez?",2,"Went to find his old lady, hasn't called, nobody's called"}},
{"fw_ld7_poa_0006","panic_days",2,"reg=outlaw,raider,gang,club,crime,prison|day=0,4|mood=fear",{1,"Don't touch him, he's sweating through everything",2,"He's my cousin!",1,"He's burning UP, look at his eyes!",2,"Then I'll wait with him, you go on, go ahead, don't let me stop you"}},
{"fw_ld7_poa_0007","panic_days",2,"reg=outlaw,raider,gang,club,crime,prison|day=0,4|mood=funny",{1,"Funny thing, I actually miss the cops",2,"Hahaha, you and me both",1,"At least they'd lock me up somewhere with a bunk",2,"And a toilet, God, I miss a toilet"}},
{"fw_ld7_poa_0008","panic_days",2,"reg=outlaw,raider,gang,club,crime,prison|day=0,4|mood=angry",{1,"I ain't scared",2,"Your hand's shaking",1,"It's the coffee",2,"You don't have a coffee, asshole, you're holding a flashlight"}},
{"fw_ld7_poa_0009","panic_days",2,"reg=outlaw,raider,gang,club,crime,prison|day=0,4|mood=grim",{1,"Where's everybody going?",2,"Same place we are",1,"Where's that?",2,"Nowhere, we're just walking, I don't have a plan, do you have a plan?"}},
{"fw_ld7_poa_0010","panic_days",2,"reg=outlaw,raider,gang,club,crime,prison|tmp=fresh|day=0,4|mood=fear",{1,"Grab the beer, grab all the beer",2,"What are you, nuts, we've got to get out of here!",1,"We'll need it later, we'll need something later!",2,"Fine, fine, one case, ONE case, hurry up!"}},
{"fw_ld7_poa_0011","panic_days",2,"reg=outlaw,raider,gang,club,crime,prison|day=0,4|mood=angry",{1,"Hey, you, get off my truck",2,"It's not yours",1,"It's mine now, I found it first",2,"Look around, man, ain't nobody gonna care who owns it by the weekend"}},
{"fw_ld7_poa_0012","panic_days",2,"reg=outlaw,raider,gang,club,crime,prison|day=0,4|mood=fear",{1,"Is it AIDS? Somebody said it's like AIDS",2,"Don't be stupid",1,"Then what is it?",2,"I don't know, but nobody got AIDS and walked into a man's yard and bit him"}},
{"fw_ld7_poa_0013","panic_days",2,"reg=outlaw,raider,gang,club,crime,prison|day=0,4|mood=grim",{1,"Saw a guy at the pawn shop with a shotgun, wouldn't let nobody in",2,"Smart",1,"He was crying, too, just standing there with the gun, crying",2,"Yeah, I'd do both"}},
{"fw_ld7_poa_0014","panic_days",2,"reg=outlaw,raider,gang,club,crime,prison|day=0,4|mood=fear",{1,"Where'd the guards go?",2,"Gone, all gone, left the keys in the lock",1,"Left us a whole building full of people who don't know what to do",2,"Which is why I'm going, and I'd go faster if you'd quit talking"}},
{"fw_ld7_poa_0015","panic_days",2,"reg=outlaw,raider,gang,club,crime,prison|day=0,4|mood=angry",{1,"Stay behind me, I'll handle it",2,"You'll handle it? You almost cried!",1,"I did NOT cry!",2,"Then what's that on your face?"}},
{"fw_ld7_poa_0016","panic_days",2,"reg=outlaw,raider,gang,club,crime,prison|day=0,4|mood=fear",{1,"Heard a lady on the radio say the president's gone",2,"Gone where?",1,"Just gone, she kept saying it, \"the president's gone, the president's gone\"",2,"Then nobody's driving, nobody's driving the whole damn country"}},
{"fw_ld7_poa_0017","panic_days",2,"reg=outlaw,raider,gang,club,crime,prison|day=0,4|mood=grim",{1,"Got any smokes?",2,"Last one",1,"Give it here",2,"Say please, go on, say it"}},
{"fw_ld7_poa_0018","panic_days",2,"reg=outlaw,raider,gang,club,crime,prison|tmp=fresh|day=0,4|mood=fear",{1,"Yo, yo, yo, which way, which WAY",2,"Shut up, shut up, let me think",1,"There's like ten of 'em, I can't count!",2,"I said shut up! Run first, think later, GO!"}},
{"fw_ld7_poa_0019","panic_days",2,"reg=outlaw,raider,gang,club,crime,prison|day=0,4|mood=funny",{1,"I got a theory",2,"Oh God",1,"The government did it, they put it in the Pepsi",2,"Hahaha- no, that's a stupid theory, but I'm drinking water now anyway"}},
{"fw_ld7_poa_0020","panic_days",2,"reg=outlaw,raider,gang,club,crime,prison|day=0,4|mood=grim",{1,"You ever kill anybody?",2,"Before this?",1,"Before, after, whatever, I'm just asking",2,"Don't ask me that, not out here, not with them listening"}},
{"fw_ld7_poa_0021","panic_days",2,"reg=outlaw,raider,gang,club,crime,prison|day=0,4|mood=fear",{1,"Hold up, hold up, somebody's following us",2,"Who?",1,"I don't know, there's a guy back there walking funny, he's been behind us for a mile",2,"Walking funny how?"}},
{"fw_ld7_poa_0022","panic_days",2,"reg=outlaw,raider,gang,club,crime,prison|day=0,4|mood=angry",{1,"The old man at the gas station shot at us!",2,"Because you broke his window!",1,"He was gonna die anyway, everybody's gonna die!",2,"That's the dumbest thing you ever said, and I've known you since sixth grade"}},
{"fw_ld7_poa_0023","panic_days",2,"reg=outlaw,raider,gang,club,crime,prison|day=0,4|mood=sad",{1,"My mom lives in Brandenburg",2,"So?",1,"So I haven't called her in two years",2,"Then go see her, you idiot, go knock on her door before it's too late"}},
{"fw_ld7_poa_0024","panic_days",2,"reg=outlaw,raider,gang,club,crime,prison|day=0,4|mood=grim",{1,"How much ammo have we got?",2,"Not enough",1,"How much is not enough?",2,"Count the clips, we've got four, and about thirty of them out there, you do the math"}},
{"fw_ld7_poa_0025","panic_days",2,"reg=outlaw,raider,gang,club,crime,prison|day=0,4|mood=fear",{1,"I wouldn't go into a house just because it looked empty",2,"Even if nobody answered?",1,"Especially then. I've heard a TV inside and no voices",2,"Could be somebody left it on. Could be something else. I'd rather look than argue about it"}},
{"fw_ld7_poa_0026","panic_days",2,"reg=outlaw,raider,gang,club,crime,prison|day=0,4|mood=angry",{1,"You said we'd be safe if we stuck with you",2,"I said safer",1,"This isn't safer, this is a coffin with wheels!",2,"Then get out and walk, go ahead, leave my ride, see how far you get"}},
{"fw_ld7_poa_0027","panic_days",2,"reg=outlaw,raider,gang,club,crime,prison|day=0,4|mood=funny",{1,"Hey, if the world ends, can I have your boots?",2,"The world's not ending",1,"Hahaha, then why are you whispering?",2,"Because I'm- shut up, shut up, they've got ears"}},
{"fw_ld7_poa_0028","panic_days",2,"reg=outlaw,raider,gang,club,crime,prison|day=0,4|mood=grim",{1,"Boss isn't answering",2,"Did you try the other number?",1,"I tried every number, there's just a busy signal, forever",2,"Then we don't have a boss, we've got ourselves"}},
{"fw_ld7_poa_0029","panic_days",2,"reg=outlaw,raider,gang,club,crime,prison|day=0,4|mood=fear",{1,"It's like they don't even feel it, I hit him with a pipe and he kept coming",2,"Hit him again",1,"I did, I did, I hit him four times!",2,"Then you didn't hit him in the right place, aim for the head, I heard that somewhere"}},
{"fw_ld7_poa_0030","panic_days",2,"reg=outlaw,raider,gang,club,crime,prison|day=0,4|mood=angry",{1,"I got a bad feeling about the guy with the limp",2,"Everybody's got a bad feeling!",1,"He's been looking at us funny, I'm telling you, he's one of 'em",2,"Then why's he still talking? One of 'em wouldn't be talking"}},
{"fw_ld7_poa_0031","panic_days",2,"reg=outlaw,raider,gang,club,crime,prison|day=0,4|mood=fear",{1,"I thought I was tough",2,"You are tough",1,"I'm not, I'm not tough, I almost pissed myself back there",2,"Join the club, man, I did"}},
{"fw_ld7_poa_0032","panic_days",2,"reg=outlaw,raider,gang,club,crime,prison|day=0,4|mood=grim",{1,"How long till they find us?",2,"Who, the cops?",1,"No, THEM",2,"Quiet, don't say it, keep walking, they like it when you talk"}},
{"fw_ld7_pra_0001","panic_days",2,"reg=civilian,family,worker,rescue|r1=civilian,family,worker,rescue|r2=rescue|day=0,4|mood=fear",{1,"Is it catching? Can I catch it from you? You've been touching people all day!",2,"I don't know",1,"That's it? You don't know?",2,"I've been touching people since this started and I'm still standing here, that's all I've got"}},
{"fw_ld7_pra_0002","panic_days",2,"reg=civilian,family,worker,rescue|r1=civilian,family,worker,rescue|r2=rescue|day=0,4|mood=sad",{1,"Can you do anything for him? Anything at all?",2,"I can sit with him",1,"That's NOT anything!",2,"It's the only thing I haven't run out of, so I'm gonna do it, you're welcome to join me"}},
{"fw_ld7_pra_0003","panic_days",2,"reg=civilian,family,worker,rescue|r1=civilian,family,worker,rescue|r2=rescue|day=0,4|mood=grim",{1,"What do we do with the ones who don't get back up?",2,"Cover them",1,"Cover them with what?",2,"Whatever's closest, a coat, a sheet, a flag if you've got one, just cover their faces"}},
{"fw_ld7_pra_0004","panic_days",2,"reg=civilian,family,worker,rescue|r1=rescue|r2=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"Is anyone hurt in your group? Anyone at all?",2,"My husband's got a cut on his hand, from the glass",1,"Show me, quick, hold it up to the light",2,"It's just glass, it's glass, I picked out the glass myself!"}},
{"fw_ld7_pra_0005","panic_days",2,"reg=civilian,family,worker,rescue|r1=civilian,family,worker,rescue|r2=rescue|day=0,4|mood=angry",{1,"Where's the nearest help?",2,"You're looking at it",1,"THAT'S not help, you look worse than I do!",2,"Then we're even, and we should probably sit down before one of us falls over"}},
{"fw_ld7_pra_0006","panic_days",2,"reg=civilian,family,worker,rescue|r1=civilian,family,worker,rescue|r2=rescue|tmp=fresh|day=0,4|mood=fear",{1,"Did you see what happened at the school? Please tell me you didn't see it",2,"I saw",1,"Was it... were there kids?",2,"Don't ask me that, please, don't ask me that"}},
{"fw_ld7_pra_0007","panic_days",2,"reg=civilian,family,worker,rescue|r1=rescue|r2=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"How long since the bite?",2,"An hour, maybe two",1,"How do you feel?",2,"Hot, I feel hot, and my arm's- it's tingling, it's going numb, is that bad? Is that bad?"}},
{"fw_ld7_pra_0008","panic_days",2,"reg=civilian,family,worker,rescue|r1=civilian,family,worker,rescue|r2=rescue|day=0,4|mood=sad",{1,"Is there any medicine? Anything?",2,"I don't know what you're asking it to treat. I can't promise an answer out of a bottle",1,"Please, I'll pay, I'll give you everything I've got!",2,"I know you're scared. Don't pay somebody just for saying they've got a cure"}},
{"fw_ld7_pra_0009","panic_days",2,"reg=civilian,family,worker,rescue|r1=civilian,family,worker,rescue|r2=rescue|day=0,4|mood=fear",{1,"My little brother stopped moving, will you look at him?",2,"Where is he?",1,"Right here, he was fine a minute ago, he just went quiet!",2,"Let me see, give him to me, no, don't leave, stay where I can see you"}},
{"fw_ld7_pra_0010","panic_days",2,"reg=civilian,family,worker,rescue|r1=civilian,family,worker,rescue|r2=rescue|day=0,4|mood=grim",{1,"How are you still going?",2,"I'm not, I'm just not stopped yet",1,"What's the difference?",2,"About an hour, I'd say, and I'm gonna enjoy that hour"}},
{"fw_ld7_pra_0011","panic_days",2,"reg=civilian,family,worker,rescue|r1=civilian,family,worker,rescue|r2=rescue|day=0,4|mood=angry",{1,"Why didn't anybody warn us?",2,"Somebody did",1,"Who?",2,"Somebody, somewhere, maybe, I don't know who got the message, I just know I didn't"}},
{"fw_ld7_pra_0012","panic_days",2,"reg=civilian,family,worker,rescue|r1=rescue|r2=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"Nobody goes near the back, understood? Not one person",2,"What's back there?",1,"People who need things I don't have, and it's not safe, I'm begging you",2,"I won't go, I won't, I promise, we'll all stay out here"}},
{"fw_ld7_pra_0013","panic_days",2,"reg=civilian,family,worker,rescue|r1=civilian,family,worker,rescue|r2=rescue|day=0,4|mood=sad",{1,"Say something comforting, you're good at it",2,"I'm not good at it",1,"Please, anything, I'm falling apart",2,"Okay, okay, I'm here, I'm not leaving, that's all I've got"}},
{"fw_ld7_pra_0014","panic_days",2,"reg=civilian,family,worker,rescue|r1=civilian,family,worker,rescue|r2=rescue|day=0,4|mood=calm",{1,"You should eat something",2,"I will",1,"When?",2,"When I've seen the last person, and I don't know who that is, so ask me again in an hour"}},
{"fw_ld7_pra_0015","panic_days",2,"reg=civilian,family,worker,rescue|r1=civilian,family,worker,rescue|r2=rescue|day=0,4|mood=fear",{1,"What if it comes back? What if it's in the town forever?",2,"Then we'll know a lot more about forever than we do now",1,"That's not funny!",2,"It wasn't supposed to be, I'm just tired of pretending I know"}},
{"fw_ld7_pra_0016","panic_days",2,"reg=rescue|r1=rescue|r2=rescue|role=rescue_medical|day=0,4|mood=grim",{1,"ER's got forty people in the hall and two doctors",2,"Two? Where'd the third go?",1,"Out front, throwing up, I told him to sit",2,"Don't tell the patients, don't tell anybody"}},
{"fw_ld7_pra_0017","panic_days",2,"reg=rescue|r1=rescue|r2=rescue|role=rescue_medical|day=0,4|mood=fear",{1,"He was fine when he came in, a scratch on the forearm, nothing",2,"And now?",1,"Fever, then he stopped answering me, then he- I had to leave the room",2,"Don't write it down, I don't want it written down"}},
{"fw_ld7_pra_0018","panic_days",2,"reg=rescue|r1=rescue|r2=rescue|role=rescue_medical|day=0,4|mood=angry",{1,"We're out of gloves",2,"Then wash your hands, wash them again",1,"With what? The water's brown!",2,"Then use the sanitizer, use the bottled water, use whatever, I've got nothing else"}},
{"fw_ld7_pra_0019","panic_days",2,"reg=rescue|r1=rescue|r2=rescue|role=rescue_medical|day=0,4|mood=sad",{1,"I took an oath",2,"I know",1,"I didn't take THIS oath, I didn't promise this",2,"Neither did I, and I'm still here, so we'll figure out which oath that is"}},
{"fw_ld7_pra_0020","panic_days",2,"reg=rescue|r1=rescue|r2=rescue|role=rescue_medical|day=0,4|mood=grim",{1,"Triage tags, how many black?",2,"We ran out of black",1,"Use red, put a line through it",2,"Nobody ever put a line through red before, I'm just saying"}},
{"fw_ld7_pra_0021","panic_days",2,"reg=rescue|r1=rescue|r2=rescue|role=rescue_medical|day=0,4|mood=fear",{1,"The lab said it's not rabies",2,"Then what is it?",1,"They didn't finish the sentence, the line went dead, I stood there holding the phone",2,"Hang it up, put it down, it's not going to ring"}},
{"fw_ld7_pra_0022","panic_days",2,"reg=rescue|r1=rescue|r2=rescue|role=rescue_medical|day=0,4|mood=sad",{1,"I haven't sat down in twenty hours",2,"Sit",1,"If I sit, I won't stand",2,"Then I'll stand for both of us, go, five minutes, I'll hold the fort"}},
{"fw_ld7_pra_0023","panic_days",2,"reg=rescue|r1=rescue|r2=rescue|role=rescue_medical|day=0,4|mood=fear",{1,"How many are restrained?",2,"Four",1,"Check the straps again",2,"I checked them ten minutes ago, they're fine, they're pulling but they're fine"}},
{"fw_ld7_pra_0024","panic_days",2,"reg=rescue|r1=rescue|r2=rescue|role=rescue_medical|day=0,4|mood=angry",{1,"The administrator left",2,"Left where?",1,"Left, in his own car, with his own family, he told us to stay",2,"Then we stay, because someone has to, and I'm not going to hate him until tomorrow"}},
{"fw_ld7_pra_0025","panic_days",2,"reg=rescue|r1=rescue|r2=rescue|role=rescue_medical|day=0,4|mood=grim",{1,"Is it too late to start boiling instruments?",2,"It's never too late for that",1,"Where's the pot?",2,"In the cafeteria, I'll go, I need to walk anyway"}},
{"fw_ld7_pra_0026","panic_days",2,"reg=rescue|r1=rescue|r2=rescue|role=rescue_firefighter|day=0,4|mood=grim",{1,"We ran forty calls and I couldn't tell you which was which",2,"Neither could I",1,"Where's the chief?",2,"Left with the first rig, they haven't radioed since"}},
{"fw_ld7_pra_0027","panic_days",2,"reg=rescue|r1=rescue|r2=rescue|role=rescue_firefighter|day=0,4|mood=angry",{1,"Hydrant's dry",2,"What?",1,"Hydrant's DRY, the pressure's gone, the whole plant's down, we've got nothing!",2,"Then let it burn, let it burn, we can't save it anyway"}},
{"fw_ld7_pra_0028","panic_days",2,"reg=rescue|r1=rescue|r2=rescue|role=rescue_firefighter|day=0,4|mood=fear",{1,"Fire doesn't scare me, I've walked into fire",2,"I know",1,"This is different. I'm scared out of my mind, and I can't keep it to myself",2,"You're not the only one. Hell, I'm glad you said it"}},
{"fw_ld7_pra_0029","panic_days",2,"reg=rescue|r1=rescue|r2=rescue|role=rescue_firefighter|day=0,4|mood=sad",{1,"I pulled a girl out and she wasn't hurt, not a mark, and she wouldn't stop screaming",2,"What was she screaming?",1,"Nothing, just a sound, I don't think she'll stop, I don't think she can",2,"Where is she now?"}},
{"fw_ld7_pra_0030","panic_days",2,"reg=rescue|r1=rescue|r2=rescue|role=rescue_firefighter|day=0,4|mood=fear",{1,"Station Three's not answering",2,"Try again",1,"I've tried four times, there's just a hiss, then somebody breathing, then nothing",2,"Breathing? Somebody was breathing on the radio?"}},
{"fw_ld7_pra_0031","panic_days",2,"reg=rescue|r1=rescue|r2=rescue|role=rescue_firefighter|day=0,4|mood=angry",{1,"We're not firemen anymore, we're just a rig with guys in it",2,"We're still the only rig",1,"For what? There's nothing to put out!",2,"Then we drive, we find somebody, we drive again"}},
{"fw_ld7_pra_0032","panic_days",2,"reg=rescue|r1=rescue|r2=rescue|role=rescue_firefighter|day=0,4|mood=grim",{1,"I keep getting calls for people locked in, they're saying, \"I'm locked in, please come\"",2,"And?",1,"We go, we get there, and the locks are fine, it's the people that aren't",2,"Stop, I don't want to know what you found"}},
{"fw_ld7_pra_0033","panic_days",2,"reg=rescue|r1=rescue|r2=rescue|role=rescue_firefighter|day=0,4|mood=fear",{1,"How much diesel do we have?",2,"A quarter tank",1,"That's maybe twenty miles",2,"Then we make twenty miles count, we pick someplace and we hold it"}},
{"fw_ld7_pra_0034","panic_days",2,"reg=rescue|r1=rescue|r2=rescue|role=rescue_clergy|day=0,4|mood=sad",{1,"I've buried six since breakfast and I've got no more words",2,"Then don't use words",1,"What do I use?",2,"Your hands, hold their hands, just hold them, they don't need the right words"}},
{"fw_ld7_pra_0035","panic_days",2,"reg=rescue|r1=rescue|r2=rescue|role=rescue_clergy|day=0,4|mood=grim",{1,"A man asked me if God was punishing us",2,"What did you say?",1,"I said I didn't know, which I'm not supposed to say",2,"It's the truest thing you could have said, that's what the Lord wants from us today"}},
{"fw_ld7_pra_0036","panic_days",2,"reg=rescue|r1=rescue|r2=rescue|role=rescue_clergy|day=0,4|mood=fear",{1,"Do I say the prayer for the dead over them?",2,"They're not dead",1,"They're not alive either, and they're in the sanctuary!",2,"Then say it for us, say it quietly, say it for the ones who are watching"}},
{"fw_ld7_pra_0037","panic_days",2,"reg=rescue|r1=rescue|r2=rescue|role=rescue_clergy|day=0,4|mood=sad",{1,"Lord forgive me, I locked the church",2,"You did what you had to",1,"There were people knocking, I could hear them, I stood there and I didn't open it",2,"God heard that too, and He also knows why"}},
{"fw_ld7_pra_0038","panic_days",2,"reg=rescue|r1=rescue|r2=rescue|role=rescue_clergy|day=0,4|mood=fear",{1,"I can't get the words to come, the Twenty-third Psalm, I know it, I know it, it won't come",2,"\"The Lord is my shepherd\"",1,"\"I shall not want,\" yes, yes, \"He maketh me to lie down\"",2,"\"In green pastures,\" keep going, I'll say it with you"}},
{"fw_ld7_pra_0039","panic_days",2,"reg=rescue|r1=rescue|r2=rescue|role=rescue_clergy|day=0,4|mood=grim",{1,"The pews are full of sleeping people",2,"Let them sleep",1,"What if they're not sleeping? What if some of them-",2,"Then we'll find out when they wake up, and we'll be here, that's all we can do"}},
{"fw_ld7_pra_0040","panic_days",2,"reg=rescue|r1=rescue|r2=rescue|role=rescue_clergy|day=0,4|mood=sad",{1,"Is it a sin to be angry at God?",2,"I've been angry all day",1,"You have?",2,"I've yelled at Him out back, and I felt better, so I think we're alright"}},
{"fw_ld7_pra_0041","panic_days",2,"reg=rescue|r1=rescue|r2=rescue|role=rescue_clergy|day=0,4|mood=fear",{1,"I remember crowds coming to church wanting answers",2,"I remember",1,"I felt like all I had was a Bible and cold coffee",2,"Maybe they came to see somebody who'd stay and listen"}},
{"fw_ld7_pwa_0001","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear|world=road",{1,"Stay off the road, stay off the road, they see you from the road",2,"Then where do we walk?!",1,"In the grass, in the ditch, anywhere but the open!",2,"My shoes are making noise on the gravel, I can't- I'm trying"}},
{"fw_ld7_pwa_0002","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=grim|world=road",{1,"There's a man lying in the middle of the street and everybody's just walking around him",2,"Maybe he's hurt",1,"Maybe, but nobody's stopping, look at 'em, nobody's even slowing down",2,"Then I'll check, cover me, I'll just see if he's breathing"}},
{"fw_ld7_pwa_0003","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear|world=road",{1,"Don't cross the street yet, wait, wait for it to pass",2,"For what to pass?",1,"Whatever that was, did you hear it, that dragging?",2,"I hear it, I hear it, it's turning the corner, get down"}},
{"fw_ld7_pwa_0004","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=angry|world=road",{1,"The whole highway's backed up to the bridge, nobody's moving",2,"Why not?",1,"Because the Guard's at the bridge, and nobody's getting past them, and nobody's turning around",2,"Then they're sitting ducks, every one of them, sitting right out in the open"}},
{"fw_ld7_pwa_0005","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=grim|world=road",{1,"Walk in the grass, not on the sidewalk, it echoes",2,"You think they hear footsteps?",1,"I think they hear everything, I think they've got ears like dogs",2,"Okay, okay, grass, I'm walking like a ninja, don't laugh"}},
{"fw_ld7_pwa_0006","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|hour=16,5|mood=fear",{1,"The streetlights are all flickering",2,"It's the power, it's about to go out",1,"What happens when it goes out?",2,"Nothing, it gets dark, that's all, it just gets dark, don't panic"}},
{"fw_ld7_pwa_0007","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear|world=cars,road",{1,"There's glass all over the road",2,"From what?",1,"From the cars, from the stores, everybody broke everything, look at it",2,"Then be careful, shoes, check your shoes, one cut and you're slow"}},
{"fw_ld7_pwa_0008","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=fear|world=road",{1,"Is the alley clear?",2,"I think so",1,"You THINK?",2,"I can't see around the dumpster, you go look, I'll wait here, I'll hold your bag"}},
{"fw_ld7_pwa_0009","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=sad|world=road",{1,"The parking lot's full, nobody's coming back for any of them",2,"Look at the kid seats, look, there's a lunchbox",1,"Don't look at the lunchbox",2,"I can't stop looking at it"}},
{"fw_ld7_pwa_0010","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear|world=vehicle",{1,"Get in the car! GET IN THE CAR!",2,"I'm in, I'm in, GO!",1,"It won't start, why won't it start?!",2,"Try again, try again, try again, TURN IT!"}},
{"fw_ld7_pwa_0011","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"We're out of gas",2,"We can't be out of gas",1,"The needle's been on E for ten miles, I kept saying it'd make it",2,"Then we're walking, grab what you can, we're walking from here"}},
{"fw_ld7_pwa_0012","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=fear",{1,"Who's got the keys? WHO HAS THE KEYS?",2,"I thought you had them",1,"I gave them to YOU!",2,"They're in the ignition, they're in the- they've been in the ignition the whole time"}},
{"fw_ld7_pwa_0013","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear|world=vehicle",{1,"I keep picturing hiding under a truck",2,"What if there wasn't room?",1,"I know. Panic keeps telling me hide before I even see a place",2,"I'd worry about getting stuck. Let's look at what we can actually use"}},
{"fw_ld7_pwa_0014","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=angry",{1,"Somebody's horn is stuck, it's been going for twenty minutes",2,"It's bringing them all in",1,"Then somebody go smash it!",2,"You go smash it, go ahead, be my guest"}},
}
